import{_ as a,o as n,c as s,ag as l}from"./chunks/framework.CmaAMB6e.js";const c=JSON.parse('{"title":"Linux 学习路径","description":"","frontmatter":{},"headers":[],"relativePath":"linux/learning-path.md","filePath":"linux/learning-path.md","lastUpdated":null}'),r={name:"linux/learning-path.md"};function i(o,t,e,d,g,p){return n(),s("div",null,[...t[0]||(t[0]=[l(`<h1 id="linux-学习路径" tabindex="-1">Linux 学习路径 <a class="header-anchor" href="#linux-学习路径" aria-label="Permalink to &quot;Linux 学习路径&quot;">​</a></h1><blockquote><p>Linux 专属的概念序列与阶段划分。每个概念自成闭环,不与其他技能绑定。Linux 是后端开发者的「战场」——代码最终跑在 Linux 服务器上,不懂 Linux 等于「写了代码但不会让它上线」。</p><p><strong>定位说明</strong>：使用者是前端工程师（macOS 用户），对命令行有基础但不懂服务器运维。本线从命令基础讲到服务器运维与容器,直达资深。</p></blockquote><h2 id="学习策略" tabindex="-1">学习策略 <a class="header-anchor" href="#学习策略" aria-label="Permalink to &quot;学习策略&quot;">​</a></h2><ul><li><strong>概念驱动</strong>:按概念顺序推进,每个概念是一篇完整教程</li><li><strong>前端对照</strong>:每篇末尾有「前端对照」小节,用你已会的 macOS 终端/命令行帮助理解</li><li><strong>边学边练</strong>:每篇配练习建议,可用 <code>/practice linux &lt;概念&gt;</code> 生成针对性练习</li></ul><h2 id="阶段总览" tabindex="-1">阶段总览 <a class="header-anchor" href="#阶段总览" aria-label="Permalink to &quot;阶段总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>主题</th><th>概念数</th></tr></thead><tbody><tr><td>1</td><td>基础层</td><td>5</td></tr><tr><td>2</td><td>核心能力层</td><td>5</td></tr><tr><td>3</td><td>工程层</td><td>5</td></tr><tr><td>4</td><td>服务器运维层</td><td>5</td></tr><tr><td>5</td><td>资深层</td><td>8</td></tr><tr><td>6</td><td>综合实战</td><td>1</td></tr></tbody></table><hr><h2 id="阶段-1-·-基础层" tabindex="-1">阶段 1 · 基础层 <a class="header-anchor" href="#阶段-1-·-基础层" aria-label="Permalink to &quot;阶段 1 · 基础层&quot;">​</a></h2><p>建立 Linux 命令行基础。macOS 用户对终端不陌生,本阶段聚焦 Linux 特有概念。</p><ul><li><strong>01 Linux 与命令行入门</strong> - 发行版、shell、基本导航（ls/cd/pwd）</li><li><strong>02 文件系统</strong> - 目录结构（/etc /var /home）、文件类型、软硬链接</li><li><strong>03 常用命令</strong> - 文件操作（cp/mv/rm/touch）、查找（find/locate）、查看（cat/less/head/tail）</li><li><strong>04 权限管理</strong> - rwx 权限位、chmod/chown、sudo、umask</li><li><strong>05 Shell 基础</strong> - 变量、通配符、重定向、管道、命令别名</li></ul><h2 id="阶段-2-·-核心能力层" tabindex="-1">阶段 2 · 核心能力层 <a class="header-anchor" href="#阶段-2-·-核心能力层" aria-label="Permalink to &quot;阶段 2 · 核心能力层&quot;">​</a></h2><p>掌握 Linux 核心操作能力。</p><ul><li><strong>06 文本处理三剑客</strong> - grep / sed / awk</li><li><strong>07 进程管理</strong> - ps/top、kill、后台任务、守护进程、nohup</li><li><strong>08 网络基础</strong> - ifconfig/ip、ping、netstat/ss、curl/wget</li><li><strong>09 软件包管理</strong> - apt/yum、源码编译、依赖管理</li><li><strong>10 Shell 脚本入门</strong> - 脚本语法、条件、循环、函数</li></ul><h2 id="阶段-3-·-工程层" tabindex="-1">阶段 3 · 工程层 <a class="header-anchor" href="#阶段-3-·-工程层" aria-label="Permalink to &quot;阶段 3 · 工程层&quot;">​</a></h2><p>进入服务器工程化能力。</p><ul><li><strong>11 服务管理 systemd</strong> - systemctl、服务单元文件、开机自启</li><li><strong>12 定时任务</strong> - cron、crontab、at、定时任务排错</li><li><strong>13 日志管理</strong> - syslog、journalctl、logrotate、日志分析</li><li><strong>14 用户与组管理</strong> - useradd/usermod、sudoers、权限审计</li><li><strong>15 网络排查</strong> - tcpdump、ss/lsof、路由、DNS 排查、常见网络问题</li></ul><h2 id="阶段-4-·-服务器运维层" tabindex="-1">阶段 4 · 服务器运维层 <a class="header-anchor" href="#阶段-4-·-服务器运维层" aria-label="Permalink to &quot;阶段 4 · 服务器运维层&quot;">​</a></h2><p>进入真实服务器运维。</p><ul><li><strong>16 SSH 与远程管理</strong> - 密钥认证、ssh config、跳板机、scp/rsync</li><li><strong>17 防火墙</strong> - iptables/nftables、ufw、常用规则</li><li><strong>18 Web 服务器 Nginx</strong> - 静态服务、反向代理、虚拟主机、HTTPS</li><li><strong>19 性能监控</strong> - top/htop、vmstat/iostat、监控工具（Prometheus 简介）</li><li><strong>20 服务器安全基线</strong> - SSH 加固、fail2ban、系统更新、最小权限</li></ul><h2 id="阶段-5-·-资深层" tabindex="-1">阶段 5 · 资深层 <a class="header-anchor" href="#阶段-5-·-资深层" aria-label="Permalink to &quot;阶段 5 · 资深层&quot;">​</a></h2><p>进阶到资深/专家水平。</p><ul><li><strong>21 Shell 脚本进阶</strong> - 参数解析、错误处理、健壮性、重构</li><li><strong>22 自动化与 Ansible</strong> - 配置管理、Playbook、幂等性</li><li><strong>23 容器化 Docker</strong> - 镜像/容器/网络/卷、docker-compose</li><li><strong>24 虚拟化与资源限制</strong> - KVM 简介、cgroup/limits、命名空间</li><li><strong>25 负载均衡</strong> - LVS/Nginx 负载、健康检查、会话保持</li><li><strong>26 系统调优</strong> - 内核参数（sysctl）、文件描述符、内存/磁盘优化</li><li><strong>27 故障排查实战</strong> - CPU 飙高、内存泄漏、磁盘满、网络故障排查流程</li><li><strong>28 高可用与集群</strong> - 主备、keepalived、集群概念、故障演练</li></ul><h2 id="阶段-6-·-综合实战" tabindex="-1">阶段 6 · 综合实战 <a class="header-anchor" href="#阶段-6-·-综合实战" aria-label="Permalink to &quot;阶段 6 · 综合实战&quot;">​</a></h2><ul><li><strong>29 综合实战项目</strong> - 从零搭建并运维一台生产服务器</li></ul><hr><h2 id="概念依赖关系" tabindex="-1">概念依赖关系 <a class="header-anchor" href="#概念依赖关系" aria-label="Permalink to &quot;概念依赖关系&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>01 -&gt; 02 -&gt; 03 -&gt; 04 -&gt; 05          (基础层串行)</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>        06 -&gt; 07 -&gt; 08 -&gt; 09 -&gt; 10   (核心能力层)</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>        11 -&gt; 12 -&gt; 13 -&gt; 14 -&gt; 15   (工程层)</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>        16 -&gt; 17 -&gt; 18 -&gt; 19 -&gt; 20   (服务器运维层)</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>        21 -&gt; 22 -&gt; ... -&gt; 28        (资深层,进阶)</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>              29                     (实战,依赖前面全部)</span></span></code></pre></div><h2 id="进度跟踪" tabindex="-1">进度跟踪 <a class="header-anchor" href="#进度跟踪" aria-label="Permalink to &quot;进度跟踪&quot;">​</a></h2><p>每完成一个概念,在 <code>progress.md</code> 更新状态:⬜ 未开始 / 🔄 学习中 / ✅ 已掌握。</p>`,29)])])}const u=a(r,[["render",i]]);export{c as __pageData,u as default};
